def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        best = None
        start = 0
        while start < len(row):
            end = start + 1
            while end < len(row) and row[end] != row[end - 1]:
                end += 1
            if end - start >= 4:
                best = (start, end)
            start = end
        if best is not None and best[1] < len(row):
            start, end = best
            a, b = row[start], row[start + 1]
            for c in range(end, len(row)):
                expected = a if (c - start) % 2 == 0 else b
                if row[c] != expected:
                    out[r][c] = 1
    return out

